local StirrupMaker = {}
local PRODUCTS = {
    iron_stirrup = { name = "Železno streme", ironCost = 3, woodCost = 1, leatherCost = 1, time = 5, cost = 160, prestige = 3, happiness = 2, description = "Železno streme za osnovne konjenike." },
    bronze_stirrup = { name = "Bronasto streme", bronzeCost = 3, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 390, prestige = 5, happiness = 3, description = "Bronasto streme za lahko konjenico." },
    silver_stirrup = { name = "Srebrno streme", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 950, prestige = 10, happiness = 4, description = "Srebrno streme za plemiške viteze." },
    gilded_stirrup = { name = "Pozlačeno streme", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2050, prestige = 19, happiness = 5, description = "Pozlačeno streme za dvorne konjenike." },
    jewel_set_stirrup = { name = "Draguljasto streme", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4400, prestige = 35, happiness = 7, description = "Draguljasto streme za kraljevo konjenico." },
    royal_sovereign_stirrup = { name = "Kraljevski suvereno streme", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 9500, prestige = 67, happiness = 13, description = "Suvereno streme z biseri za krono." },
}
local BUILDINGS = {
    stirrup_workshop = { name = "Stremska delavnica", cost = { gold = 350, wood = 170, stone = 140, iron = 9 }, upkeep = 6, qualityBonus = 5 },
    stirrup_house = { name = "Stremska hiša", cost = { gold = 1240, wood = 355, stone = 275, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_stirrup_atelier = { name = "Mojstrski stremski atelje", cost = { gold = 3100, wood = 415, stone = 530, silver = 37, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_stirrup_palace = { name = "Suverena stremska palača", cost = { gold = 13200, wood = 635, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
StirrupMaker.ironStock = 14; StirrupMaker.bronzeStock = 12; StirrupMaker.woodStock = 10; StirrupMaker.leatherStock = 10; StirrupMaker.silverStock = 8; StirrupMaker.goldStock = 6; StirrupMaker.jewelStock = 4; StirrupMaker.pearlStock = 4
StirrupMaker.productStock = {}; StirrupMaker.buildings = {}; StirrupMaker.maker = nil; StirrupMaker.activeMaking = {}; StirrupMaker.totalProducts = 0; StirrupMaker.dayTimer = 0
function StirrupMaker.init() StirrupMaker.ironStock=14; StirrupMaker.bronzeStock=12; StirrupMaker.woodStock=10; StirrupMaker.leatherStock=10; StirrupMaker.silverStock=8; StirrupMaker.goldStock=6; StirrupMaker.jewelStock=4; StirrupMaker.pearlStock=4; StirrupMaker.productStock={}; StirrupMaker.buildings={}; StirrupMaker.maker=nil; StirrupMaker.activeMaking={}; StirrupMaker.totalProducts=0; StirrupMaker.dayTimer=0; print("[StirrupMaker] Royal Stirrup Maker System initialized (6 products, 4 buildings)") end
function StirrupMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StirrupMaker.maker={name=n or ("Stremar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stremar najet: %s (spretnost: %d)",StirrupMaker.maker.name,s),"success") end; return true end
function StirrupMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StirrupMaker.build(id) local ok,e=StirrupMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StirrupMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StirrupMaker.getQualityBonus() local b=0; for _,bd in ipairs(StirrupMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StirrupMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and StirrupMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and StirrupMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and StirrupMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and StirrupMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and StirrupMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StirrupMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StirrupMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StirrupMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StirrupMaker.buildings==0 then return false,"Potrebna stremska delavnica" end; if not StirrupMaker.maker then return false,"Potreben stremar" end; return true end
function StirrupMaker.make(pt,qty) qty=qty or 1; local ok,e=StirrupMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then StirrupMaker.ironStock=StirrupMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then StirrupMaker.bronzeStock=StirrupMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then StirrupMaker.woodStock=StirrupMaker.woodStock-d.woodCost*qty end; if d.leatherCost then StirrupMaker.leatherStock=StirrupMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then StirrupMaker.silverStock=StirrupMaker.silverStock-d.silverCost*qty end; if d.goldCost then StirrupMaker.goldStock=StirrupMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StirrupMaker.jewelStock=StirrupMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StirrupMaker.pearlStock=StirrupMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StirrupMaker.maker then t=math.max(1,t-math.floor(StirrupMaker.maker.skill/13)) end; table.insert(StirrupMaker.activeMaking,{id="stirrup_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StirrupMaker.completeMaking(m) local q=1.0+(StirrupMaker.getQualityBonus()/100); if StirrupMaker.maker then q=q+(StirrupMaker.maker.skill/140) end; q=math.min(2.5,q); StirrupMaker.productStock[m.productType]=(StirrupMaker.productStock[m.productType] or 0)+m.quantity; StirrupMaker.totalProducts=StirrupMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StirrupMaker.maker then StirrupMaker.maker.itemsMade=StirrupMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StirrupMaker.maker.skill=math.min(100,StirrupMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Streme izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"stirrup.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function StirrupMaker.update(dt) if not _G.state then return end; StirrupMaker.dayTimer=StirrupMaker.dayTimer+dt; if StirrupMaker.dayTimer>=30 then StirrupMaker.dayTimer=0; for i=#StirrupMaker.activeMaking,1,-1 do local m=StirrupMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StirrupMaker.completeMaking(m); table.remove(StirrupMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StirrupMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StirrupMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StirrupMaker.getStats() return {ironStock=StirrupMaker.ironStock,bronzeStock=StirrupMaker.bronzeStock,woodStock=StirrupMaker.woodStock,leatherStock=StirrupMaker.leatherStock,silverStock=StirrupMaker.silverStock,goldStock=StirrupMaker.goldStock,jewelStock=StirrupMaker.jewelStock,pearlStock=StirrupMaker.pearlStock,productStock=StirrupMaker.productStock,numBuildings=#StirrupMaker.buildings,hasMaker=StirrupMaker.maker~=nil,makerName=StirrupMaker.maker and StirrupMaker.maker.name or "—",makerSkill=StirrupMaker.maker and StirrupMaker.maker.skill or 0,activeMaking=#StirrupMaker.activeMaking,totalProducts=StirrupMaker.totalProducts} end
return StirrupMaker
